def _strip_prompts(prompt_re, initial_re=None):


    if initial_re is None:
        initial_re = prompt_re
    line = ''
    while True:
        line = (yield line)

        # First line of cell
        if line is None:
            continue
        out, n1 = initial_re.subn('', line, count=1)
        line = (yield out)

        if line is None:
            continue
        # check for any prompt on the second line of the cell,
        # because people often copy from just after the first prompt,
        # so we might not see it in the first line.
        out, n2 = prompt_re.subn('', line, count=1)
        line = (yield out)

        if n1 or n2:
            # Found a prompt in the first two lines - check for it in
            # the rest of the cell as well.
            while line is not None:
                line = (yield prompt_re.sub('', line, count=1))

        else:
            # Prompts not in input - wait for reset
            while line is not None:
                line = (yield line)

def _get_ignored_params(
    root_module: torch.nn.Module,
    ignored_modules: Set[torch.nn.Module],
    ignored_parameters: Optional[Iterable[torch.nn.Parameter]] = None,
) -> Set[torch.nn.Parameter]:



    all_ignored_params: Set[torch.nn.Parameter] = set()

    params_in_ignored_modules = set(
        p
        for m in ignored_modules
        for p in m.parameters()
        if not _is_fsdp_flattened(p)
    )

    all_ignored_params.update(params_in_ignored_modules)

    if ignored_parameters is not None:
        params_in_ignored_parameters = set(
            p
            for p in ignored_parameters
            if not _is_fsdp_flattened(p)
        )
        all_ignored_params.update(params_in_ignored_parameters)

        # Include nested FSDP modules' ignored parameters
        for submodule in root_module.modules():
            optional_fsdp_state = _get_module_fsdp_state(submodule)
            if optional_fsdp_state is not None:
                assert hasattr(optional_fsdp_state, "_ignored_params")
                all_ignored_params.update(optional_fsdp_state._ignored_params)

    return all_ignored_params

