        return y, new_cache

def win32InstalledFonts(directory=None, fontext='ttf'):



    import winreg

    if directory is None:
        directory = win32FontDirectory()

    fontext = ['.' + ext for ext in get_fontext_synonyms(fontext)]

    items = set()
    for fontdir in MSFontDirectories:
        # System fonts
        try:
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, fontdir) as local:
                for j in range(winreg.QueryInfoKey(local)[1]):
                    # Usually, value contains the name of the font file.
                    key, value, tp = winreg.EnumValue(local, j)
                    if not isinstance(value, str):
                        continue
                    # Work around for https://bugs.python.org/issue25778, which
                    # is fixed in Py>=3.6.1.
                    value = value.split("\0", 1)[0]
                    try:
                        path = Path(directory, value).resolve()
                    except RuntimeError:
                        # Don't fail with invalid entries.
                        continue
                    if path.suffix.lower() in fontext:
                        items.add(str(path))
        except (OSError, MemoryError):
            continue

        # User fonts
        try:
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, fontdir) as local:
                for j in range(winreg.QueryInfoKey(local)[1]):
                    # Usually, value contains the absolute path to the font
                    # file.
                    key, value, tp = winreg.EnumValue(local, j)
                    if not isinstance(value, str):
                        continue
                    try:
                        path = Path(value).resolve()
                    except RuntimeError:
                        # Don't fail with invalid entries.
                        continue
                    if path.suffix.lower() in fontext:
                        items.add(str(path))
        except (OSError, MemoryError):
            continue

    return list(items)

def findSystemFonts(fontpaths=None, fontext='ttf'):



    fontfiles = {}

    if fontpaths is None:
        if sys.platform == 'win32':
            fontdir = win32FontDirectory()

            fontpaths = [fontdir]
            # now get all installed fonts directly...
            for f in win32InstalledFonts(fontdir):
                base, ext = os.path.splitext(f)
                if len(ext)>1 and ext[1:].lower()==fontext:
                    fontfiles[f] = 1
        else:
            fontpaths = x11FontDirectory()
            # check for OS X & load its fonts if present
            if sys.platform == 'darwin':
                for f in OSXInstalledFonts():
                    fontfiles[f] = 1

            for f in get_fontconfig_fonts(fontext):
                fontfiles[f] = 1

    elif isinstance(fontpaths, (str, unicode)):
        fontpaths = [fontpaths]

    for path in fontpaths:
        files = glob.glob(os.path.join(path, '*.'+fontext))
        files.extend(glob.glob(os.path.join(path, '*.'+fontext.upper())))
        for fname in files:
            fontfiles[os.path.abspath(fname)] = 1

    return [fname for fname in fontfiles.keys() if os.path.exists(fname)]
